"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["76401"],{46143(e){e.exports=JSON.parse('{"id":"F086","slug":"solow-steady-state","name":"Solow Model Steady State","subject":"Economics for Finance","section":"How the Economy Works","topic":"Productivity and long-run growth","level":"Intermediate","aliases":["capital per worker","golden rule saving rate","long-run growth model"],"formula":{"latex":"k^{*}=\\\\left(\\\\frac{sA}{\\\\delta+n}\\\\right)^{\\\\frac{1}{1-\\\\alpha}},\\\\quad y^{*}=A\\\\,(k^{*})^{\\\\alpha},\\\\quad c^{*}=(1-s)\\\\,y^{*}","also":[],"text":"Steady-state capital per worker k* = (s x A / (depreciation + labor force growth))^(1 / (1 - alpha)); Output per worker y* = A x k*^alpha; Consumption per worker c* = (1 - s) x y*. Consumption is highest when the saving rate s equals alpha"},"symbols":[{"symbol":"s","meaning":"Saving (investment) rate","unit":"percent"},{"symbol":"A","meaning":"Productivity level","unit":"number"},{"symbol":"delta","meaning":"Depreciation rate of capital","unit":"per year"},{"symbol":"n","meaning":"Growth rate of the labor force","unit":"per year"},{"symbol":"alpha","meaning":"Capital share of income","unit":"percent"}],"when_to_use":"Use it to see why economies converge to a level of income per worker, not to ever-faster growth. Saving more raises the level of income but not its long-run growth rate; only productivity growth lifts that. Consumption is maximized at the golden-rule saving rate, and saving above it is wasteful. It is a stylized model.","worked_example":{"problem":"Saving rate 25%, productivity A = 1, depreciation 5%, labor force growth 1%, capital share 33%.","inputs":{"s":25,"a":1,"dl":5,"n":1,"al":33},"steps":[{"label":"k* = (s A / (delta + n))^(1 / (1 - alpha))","working":"(0.25 x 1 / (0.05+0.01))^(1 / (1-0.33))","value":"8.415"},{"label":"y* = A x k*^alpha","working":"1 x 8.41507^0.33","value":"2.020"},{"label":"c* = (1 - s) x y*","working":"(1-0.25) x 2.01962","value":"1.515"},{"label":"Golden-rule saving rate = alpha","working":"0.33","value":"33%"},{"label":"Saving rate minus golden rule (negative = below)","working":"0.25-0.33","value":"-8.0%"}],"answer":"Steady-state capital per worker is 8.415, giving output per worker of 2.020 and consumption per worker of 1.515. The golden-rule saving rate equals the capital share, 33%, so this economy is saving -8.0% the golden-rule level."},"calculator":{"available":true,"inputs":[{"id":"s","label":"Saving rate","unit":"%","type":"number","default":25,"hint":""},{"id":"a","label":"Productivity A","unit":"","type":"number","default":1,"hint":""},{"id":"dl","label":"Depreciation rate","unit":"%","type":"number","default":5,"hint":""},{"id":"n","label":"Labor force growth","unit":"%","type":"number","default":1,"hint":""},{"id":"al","label":"Capital share","unit":"%","type":"number","default":33,"hint":""}],"checks":[{"expr":"s>0 and dl+n>0 and al>0 and al<1","message":"Enter a saving rate and capital share between 0 and 100% and a positive depreciation plus growth."}],"steps":[{"id":"k","label":"k* = (s A / (delta + n))^(1 / (1 - alpha))","expr":"(s*a/(dl+n))^(1/(1-al))","format":"num3"},{"id":"y","label":"y* = A x k*^alpha","expr":"a*k^al","format":"num3"},{"id":"c","label":"c* = (1 - s) x y*","expr":"(1-s)*y","format":"num3"},{"id":"gold","label":"Golden-rule saving rate = alpha","expr":"al","format":"pct0"},{"id":"rel","label":"Saving rate minus golden rule (negative = below)","expr":"s-al","format":"pct1"}],"results":["k","y","c"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"k":8.415072232654058,"y":2.0196173358369744,"c":1.5147130018777308,"gold":0.33,"rel":-0.08}},"finder":{"finds":"The long-run level of output per worker","needs":"Saving rate, productivity, depreciation, labor growth, capital share"},"related":[{"slug":"growth-accounting","name":"Growth Accounting and Productivity"},{"slug":"okun-law","name":"Okun\'s Law"},{"slug":"output-gap-annualized","name":"Output Gap and Annualized Growth"}],"related_ids":["F085","F083","F081"],"group":"Money, banks and the economy","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><msup><mi>k</mi><mo lspace=\\"0em\\" rspace=\\"0em\\">\u2217</mo></msup><mo>=</mo><msup><mrow><mo fence=\\"true\\">(</mo><mfrac><mrow><mi>s</mi><mi>A</mi></mrow><mrow><mi>\u03B4</mi><mo>+</mo><mi>n</mi></mrow></mfrac><mo fence=\\"true\\">)</mo></mrow><mfrac><mn>1</mn><mrow><mn>1</mn><mo>\u2212</mo><mi>\u03B1</mi></mrow></mfrac></msup><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><msup><mi>y</mi><mo lspace=\\"0em\\" rspace=\\"0em\\">\u2217</mo></msup><mo>=</mo><mi>A</mi><mtext>\u2009</mtext><mo stretchy=\\"false\\">(</mo><msup><mi>k</mi><mo lspace=\\"0em\\" rspace=\\"0em\\">\u2217</mo></msup><msup><mo stretchy=\\"false\\">)</mo><mi>\u03B1</mi></msup><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><msup><mi>c</mi><mo lspace=\\"0em\\" rspace=\\"0em\\">\u2217</mo></msup><mo>=</mo><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>\u2212</mo><mi>s</mi><mo stretchy=\\"false\\">)</mo><mtext>\u2009</mtext><msup><mi>y</mi><mo lspace=\\"0em\\" rspace=\\"0em\\">\u2217</mo></msup></mrow><annotation encoding=\\"application/x-tex\\">k^{*}=\\\\left(\\\\frac{sA}{\\\\delta+n}\\\\right)^{\\\\frac{1}{1-\\\\alpha}},\\\\quad y^{*}=A\\\\,(k^{*})^{\\\\alpha},\\\\quad c^{*}=(1-s)\\\\,y^{*}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"sofr-futures","name":"SOFR Futures Price, Rate and Tick Value"},"next":{"slug":"sortino-ratio","name":"Sortino Ratio"},"lesson":null,"total":522}')}}]);